import math

def isPrime(num):
    num = float(num)
    if num < 4:
        return False
    i = 2
    while i < math.sqrt(num):
        if num % i == 0:
            return False
        i += 1
    return True

def calculation():
    pi = '3.'
    i = 0
    while i < len(pi) - 10:
        if isPrime(pi[i:i+10]):
            num = pi[i:i+10]
            total = 0
            for j in range(10):
                total += float(num[j:j+1])
            if total == 49:
                return num
        i += 1

if __name__ == '__main__':
    calculation()